"""Shared pytest fixtures for pointclouds."""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pytest

from pointclouds import PointCloud

#: Repository root, resolved from this file so the fixtures work whatever the invocation directory is.
_ROOT = Path(__file__).resolve().parent.parent
#: Committed sample data, regenerated by `examples/data/make_sample.py`.
_DATA = _ROOT / "examples" / "data"


@pytest.fixture
def data_dir() -> Path:
    """The committed example data directory, for tests that need the fixture generators next to it."""
    return _DATA


@pytest.fixture
def tiny_cloud() -> PointCloud:
    """A four-point cloud with classification, for core-path tests."""
    return PointCloud(
        x=np.array([0.0, 1.0, 2.0, 3.0]),
        y=np.array([0.0, 1.0, 0.0, 1.0]),
        z=np.array([5.0, 2.0, 4.0, 1.0]),
        classification=np.array([2, 5, 2, 6], dtype=np.uint8),
    )


@pytest.fixture
def sample_laz() -> Path:
    """Path to the committed 400-point LAZ sample (EPSG:28992)."""
    return _DATA / "sample.laz"


@pytest.fixture
def sample_las() -> Path:
    """Path to the committed 400-point LAS sample (EPSG:28992)."""
    return _DATA / "sample.las"


@pytest.fixture
def sample_copc() -> Path:
    """Path to the committed 1600-point COPC sample (EPSG:28992), regenerated by `make_copc_sample.py`."""
    return _DATA / "sample.copc.laz"


@pytest.fixture(params=["sample.las", "sample.laz"])
def sample_file(request) -> Path:
    """Both committed samples in turn, so every read path is exercised uncompressed and compressed."""
    return _DATA / request.param
